	}

	private IsfDataTypeWriter createDataTypeWriter(DataTypeManager dtm)
    {
		StringWriter @out = new StringWriter();
		return new IsfDataTypeWriter(dtm, null, @out);
	}

	private string writeFrom(IsfDataTypeWriter dataTypeWriter)
    {
		try {
			JsonObject @object =
				dataTypeWriter.getRootObject(TaskMonitor.DUMMY);
